export function mapTests(rows: TestRow[], selected: { test_id: string; user_id: string; position: number }[]): TestDefinition[] {
  return legacyOrder(rows, (r) => r.created_at).map(
    (r) =>
      compact({
        id: r.id,
        title: r.title,
        range_start: r.range_start,
        range_end: r.range_end,
        questions_count: r.questions_count,
        lines_per_question: r.lines_per_question,
        prerequisites: {
          require_all_quarters_completed: r.require_all_quarters_completed,
          require_revision_completed: r.require_revision_completed,
        },
        has_max_errors: r.max_errors !== null,
        max_errors_allowed: r.max_errors,
        test_type: r.test_type,
        is_active: r.status === 'published',
        audience: r.audience,
        selected_member_ids: selected
          .filter((s) => s.test_id === r.id)
          .sort((a, b) => a.position - b.position)
          .map((s) => s.user_id),
        difficulty: r.difficulty,
        created_at: iso(r.created_at),
        created_by_admin_id: r.created_by,
        updated_at: iso(r.updated_at),
        ...(r.status === 'finished' ? { is_finished: true } : {}),
        finished_at: iso(r.finished_at),
      }) as TestDefinition
  );
}

export function mapAttempts(rows: AttemptRow[], questions: QuestionRow[]): TestAttempt[] {
  const byAttempt = new Map<string, QuestionRow[]>();
  for (const q of questions) {
    const list = byAttempt.get(q.attempt_id) || [];
    list.push(q);
    byAttempt.set(q.attempt_id, list);
  }
  return legacyOrder(
    rows.filter((r) => r.status === 'passed' || r.status === 'failed'),
    (r) => r.created_at
  ).map(
    (r) =>
      compact({
        id: r.id,
        test_id: r.test_id,
        candidate_id: r.candidate_id,
        candidate_name: r.candidate_name_snapshot,
        examiner_id: r.examiner_id,
        examiner_name: r.examiner_name_snapshot,
        total_errors: r.total_errors,
        status: r.status,
        passed: r.status === 'passed',
        date: r.attempt_date,
        notes: r.notes,
        created_at: iso(r.created_at),
        effective_range_end: r.effective_range_end,
        covers_full_range: r.covers_full_range,
        questions_results: (byAttempt.get(r.id) || [])
          .sort((a, b) => a.question_number - b.question_number)
          .map(
            (q) =>
              compact({
                question_number: q.question_number,
                start_surah: q.start_surah,
                start_surah_name: q.start_surah_name,
                start_ayah: q.start_ayah,
                end_surah: q.end_surah,
                end_surah_name: q.end_surah_name,
                end_ayah: q.end_ayah,
                errors_count: q.errors_count,
                notes: q.notes,
              }) as TestAttemptQuestionResult
          ),
      }) as TestAttempt
  );
}
